import {modules,moduleCoverage} from './modules.js';
import {domains,moduleGuidance,domainRecords,reviewGaps} from './guidance.js';
import {builderView as recordEditor,setEditor,getEditor,moduleView as evidenceView} from './modules-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pageLink=(page,label)=>`<button class="btn" data-page="${page}">${esc(label)} &rarr;</button>`;
const heading=(title,sub)=>`<div class="heading"><div><div class="eyebrow">Intelligent CIO Transformation Workbench</div><h1>${title}</h1><p class="subtitle">${sub}</p></div></div>`;
function explanation(){return `<section class="panel how-it-works"><div><b>1. Describe your enterprise</b><p>Add applications, processes, teams and other records.</p></div><div><b>2. Connect the evidence</b><p>Link records, assign owners and review what is missing.</p></div><div><b>3. Explore CIO decisions</b><p>Use the same context across all twelve decision modules.</p></div></section>`;}
function moduleCard(graph,m,i){const g=moduleGuidance[m.id],c=moduleCoverage(graph,m);return `<section class="panel module-card decision-card"><div class="module-number">${String(i+1).padStart(2,'0')} <span class="tag ${m.route?'green':'orange'}">${m.route?'Demo analysis available':'Evidence workspace only'}</span></div><h2>${esc(m.name)}</h2><p class="decision-question">${esc(m.question)}</p><dl class="decision-details"><dt>Information needed</dt><dd>${esc(g.input)}</dd><dt>What you can do today</dt><dd>${esc(g.output)}</dd></dl><p class="example-line"><b>Example:</b> ${esc(g.example)}</p><div class="module-coverage">${c.nodes.length} relevant records loaded; ${c.missing.length} required record types missing.</div>${pageLink('module-'+m.id,m.route?'Explore this decision':'Review required context')}</section>`;}
export function decisionModulesView(graph){return heading('CIO Decision Modules','Choose the question you want to answer. Each module uses the same shared enterprise context.')+explanation()+`<div class="module-launch panel"><div><b>New to the workbench?</b><p>Start with the guided context builder, or explore the synthetic example already loaded.</p></div>${pageLink('builder','Start building enterprise context')}</div><div class="data-health">All 12 modules are represented. Seven connect to existing demo analysis; five currently help you inspect evidence and gaps. The AI advisor uses bounded rules. No live enterprise integrations or shared database writes are active.</div><div class="module-grid">${modules.map((m,i)=>moduleCard(graph,m,i)).join('')}</div>`;}
export function decisionModuleView(graph,id){const m=modules.find(m=>m.id===id),g=moduleGuidance[id];const original=evidenceView(graph,id);const evidence=original.slice(original.indexOf('<div class="grid-two'));
return heading(esc(m.name),esc(m.question))+`<div class="buttons">${pageLink('modules','All CIO decision modules')}${pageLink('builder','Build enterprise context')}${m.route?pageLink(m.route,g.action):''}</div><section class="panel module-card section-gap"><div class="how-it-works"><div><h2>Information you provide</h2><p>${esc(g.input)}.</p></div><div><h2>What works today</h2><p>${esc(g.output)}</p></div><div><h2>Example CIO question</h2><p>${esc(g.example)}</p></div></div>${!m.route?'<div class="data-health">This module currently organizes evidence. Its analytical engine is planned; it will not generate a recommendation yet.</div>':''}</section>${evidence}`;}
const steps=['Choose domain','Add or import records','Connect records','Validate evidence','Explore decisions'];
let journey={domain:'',step:1};
try{const s=JSON.parse(sessionStorage.getItem('cio-journey'));if(s&&domains.some(d=>d.id===s.domain)&&Number.isInteger(s.step)&&s.step>=1&&s.step<=5)journey=s;}catch{}
function remember(){try{sessionStorage.setItem('cio-journey',JSON.stringify(journey));}catch{}}
export function chooseDomain(id){if(!domains.some(d=>d.id===id))return;journey={domain:id,step:2};setEditor('node');remember();}
export function moveJourney(step){if(!Number.isInteger(step)||step<1||step>5)return;if(step>1&&!journey.domain)return;journey.step=step;if(step===2)setEditor('node');if(step===3)setEditor('edge');remember();}
export function reviewRecord(kind,id){moveJourney(kind==='edge'?3:2);setEditor(kind,id);}
function controls(){return `<div class="journey-controls">${journey.step>1?`<button class="btn" data-journey-step="${journey.step-1}">&larr; Back: ${steps[journey.step-2]}</button>`:'<span></span>'}${journey.step<5&&journey.domain?`<button class="btn primary" data-journey-step="${journey.step+1}">Next: ${steps[journey.step]} &rarr;</button>`:''}</div>`;}
function validationView(graph,d){const gaps=reviewGaps(graph,d),nodes=domainRecords(graph,d);return `<section class="panel module-card"><h2>Review the evidence before using it</h2><p>${nodes.length} records belong to this context domain. ${gaps.length} related entity or relationship records have gaps. These checks help you review the loaded snapshot; they do not certify enterprise completeness.</p><div class="data-health">Open a record to correct its evidence. Mark it validated only after review with its accountable owner. Continuing to decisions does not approve or validate any records.</div><div class="table-wrap"><table class="table"><thead><tr><th>Record</th><th>What needs attention</th><th></th></tr></thead><tbody>${gaps.map(({record:r,kind,gaps})=>`<tr><td>${esc(r.name||r.type+' relationship')}<small class="record-id">${esc(r.id)}</small></td><td>${esc(gaps.join('; '))}</td><td><button class="btn" data-review-kind="${kind}" data-review-id="${esc(r.id)}">Review record</button></td></tr>`).join('')||'<tr><td colspan="3">No gaps found by these checks. Confirm source coverage and accuracy with the data owner.</td></tr>'}</tbody></table></div>${pageLink('readiness','See enterprise-wide readiness')}</section>`;}
export function journeyView(graph){const d=domains.find(x=>x.id===journey.domain);if(!d)journey.step=1;
 const nav=`<nav class="journey-steps" aria-label="Build enterprise context steps">${steps.map((name,i)=>`<button class="journey-step ${journey.step===i+1?'active':''}" data-journey-step="${i+1}" ${!d&&i?'disabled':''} ${journey.step===i+1?'aria-current="step"':''}><span>${i+1}</span>${name}</button>`).join('')}</nav>`;
 let content='';
 if(journey.step===1)content=`${explanation()}<section class="panel module-card section-gap"><h2>Choose the part of your enterprise to describe</h2><p>A domain is a starting point for this guided journey. All records still belong to one shared graph; selecting a domain does not create a separate database or restrict access.</p><div class="domain-grid">${domains.map(x=>`<button class="domain-card" data-domain="${x.id}"><strong>${esc(x.name)}</strong><span>${esc(x.example)}</span><small>${domainRecords(graph,x).length} matching records already loaded &rarr;</small></button>`).join('')}</div></section><section class="panel module-card section-gap"><h2>A simple claims example</h2><p><b>Records:</b> Claims process, Claims application, Legacy database.</p><p><b>Connections:</b> Claims process uses Claims application. Claims application depends on Legacy database.</p><p><b>CIO decision:</b> Trace which business activities are exposed before modernizing the database.</p>${pageLink('impact','Try the existing impact demo')}</section>`;
 if(journey.step===2||journey.step===3){const kind=journey.step===2?'node':'edge';if(getEditor().kind!==kind)setEditor(kind);const raw=recordEditor(graph);let editor=raw.slice(raw.indexOf('<div class="builder-layout'));const asideStart=editor.indexOf('<section class="panel module-card"><h2>One connected enterprise');if(asideStart>=0)editor=editor.slice(0,asideStart)+'<section class="panel module-card"><h2>Help with this form</h2><p><b>Record ID:</b> A stable reference used to connect records. A new ID is filled in for you.</p><p><b>Accountable owner:</b> The team or person who can confirm this information.</p><p><b>Evidence source:</b> Where the information came from, such as an inventory or an owner interview.</p><p><b>Fact state:</b> Choose observed for current facts, proposed for a suggestion, approved-plan for an agreed future change, or hypothesis for an assumption.</p><p><b>Validated:</b> Tick only after the owner has reviewed the record.</p><h3>After saving</h3><p>The record becomes available across the graph and relevant modules. Save multiple records before continuing. A shared enterprise database is not connected to this public demo.</p></section></div>';
 content=`<section class="panel module-card"><h2>${journey.step===2?'Add the things your enterprise uses':'Describe how your records depend on each other'}</h2><p>${journey.step===2?'An entity is simply a record, such as an application, a process or a team. Choose an existing record below to edit it, or create a new one.':'A relationship connects two existing records. Choose the source, the relationship and the target. For example: Claims application DEPENDS_ON Legacy database.'}</p><p><b>Suggested record types for ${esc(d.name)}:</b> ${esc(d.types.join(', '))}.</p>${journey.step===2?`<div class="buttons"><input type="file" accept="application/json,.json" id="context-file" class="hidden"><button class="btn" data-action="import-context">Import a JSON graph</button><button class="btn" data-action="download-sample">Download example JSON</button></div><p>Import replaces the current browser graph. Use the example schema; direct spreadsheet imports and source connectors are not available yet.</p>`:`<p>Operational impact follows observed dependency relationships. Plans and hypotheses remain separate from observed facts.</p>`}</section>${editor}<p class="journey-save-note">Use <b>Add record</b> or <b>Save record</b> to save before moving to another step. Next moves the guide forward; it does not save the form.</p>`;
 }
 if(journey.step===4)content=validationView(graph,d);
 if(journey.step===5){const relevant=modules.filter(m=>d.modules.includes(m.id));content=`<section class="panel module-card"><h2>Use your context to explore a CIO decision</h2><p>Your records are shared across the graph and all relevant modules. Select a decision below. Available demo analyses use the current browser snapshot; evidence-only modules show what still needs to be collected.</p><div class="buttons">${pageLink('graph','See your enterprise graph')}<button class="btn" data-action="export-context">Export your context JSON</button>${pageLink('modules','Browse all 12 decision modules')}</div></section><div class="module-grid">${relevant.map(m=>moduleCard(graph,m,modules.indexOf(m))).join('')}</div>`;}
 return heading('Build Enterprise Context','Follow five steps to turn enterprise records into connected evidence for CIO decisions.')+nav+`<div class="journey-status">Step ${journey.step} of 5${d?' · '+esc(d.name):''}<span>Saved records stay in this browser. Export JSON to keep a copy.</span></div>`+content+controls();
}
